import {TbbSetupBudgetBanner} from '@github-ui/in-product-targeting'
import type {TbbSetupBudgetBannerProps} from '@github-ui/in-product-targeting'

export function IpmTbbSetupBudgetBannerPartial({
  entityName,
  ctaHref,
  dismissPath,
  analytics,
}: TbbSetupBudgetBannerProps) {
  if (!entityName) {
    return null
  }

  return (
    <TbbSetupBudgetBanner entityName={entityName} ctaHref={ctaHref} dismissPath={dismissPath} analytics={analytics} />
  )
}
